#!/usr/bin/env python\n# -*- coding: utf-8 -*-\n\nimport os\nimport time\nimport json\nfrom datetime import datetime\nfrom typing import Dict, List, Any, Optional, Union\nimport logging\nfrom contextlib import contextmanager\n\n# 导入所有新的profiling组件\nfrom .precision_timer import PrecisionTimer, GlobalTimerManager, time_operation\nfrom .pytorch_profiler_v2 import ModuleProfiler, LayerWiseProfiler\nfrom .onnx_profiler_v2 import ONNXProfilerV2\nfrom .performance_visualizer import PerformanceVisualizer\nfrom .cpu_optimizer import CPUPlatformDetector, PerformanceMonitor\n\nclass TesseraProfiler:\n    \"\"\"\n    Tessera统一深度性能分析器\n    \n    提供block/layer级别的精确性能分析，支持PyTorch和ONNX模型，\n    包含CPU平台优化和详细的可视化报告生成。\n    \"\"\"\n    \n    def __init__(self, output_dir: str, name: str = \"tessera_profiler\", enable_system_monitoring: bool = True):\n        self.name = name\n        self.output_dir = output_dir\n        self.enable_system_monitoring = enable_system_monitoring\n        \n        # 确保输出目录存在\n        os.makedirs(output_dir, exist_ok=True)\n        \n        # 初始化组件\n        self.timer_manager = GlobalTimerManager()\n        self.main_timer = self.timer_manager.get_timer(\"main\")\n        \n        self.cpu_detector = CPUPlatformDetector()\n        self.visualizer = PerformanceVisualizer(output_dir)\n        \n        # Profiler实例（延迟初始化）\n        self.pytorch_profiler: Optional[ModuleProfiler] = None\n        self.onnx_profiler: Optional[ONNXProfilerV2] = None\n        self.layer_profiler: Optional[LayerWiseProfiler] = None\n        \n        # 性能监控\n        self.performance_monitor = PerformanceMonitor() if enable_system_monitoring else None\n        \n        # 结果存储\n        self.profiling_results = {\n            'system_info': None,\n            'pytorch_results': None,\n            'onnx_results': None,\n            'optimization_applied': None,\n            'monitoring_data': None\n        }\n        \n        # 日志设置\n        self.logger = logging.getLogger(f\"TesseraProfiler.{name}\")\n        \n        # 获取系统信息\n        self.profiling_results['system_info'] = self.cpu_detector.get_system_info()\n        \n        self.logger.info(f\"TesseraProfiler initialized for {self.cpu_detector.cpu_info.get('vendor', 'Unknown')} CPU\")\n    \n    def optimize_for_cpu(self, model_type: str = 'onnx') -> Dict[str, str]:\n        \"\"\"\n        根据CPU平台应用优化配置\n        \n        Args:\n            model_type: 模型类型 ('pytorch', 'onnx', 'both')\n            \n        Returns:\n            应用的优化配置字典\n        \"\"\"\n        with self.main_timer.timer(\"cpu_optimization\"):\n            applied_optimizations = self.cpu_detector.apply_optimizations(model_type)\n            self.profiling_results['optimization_applied'] = applied_optimizations\n            \n            self.logger.info(f\"Applied {len(applied_optimizations)} CPU optimizations\")\n            for key, value in applied_optimizations.items():\n                self.logger.debug(f\"  {key} = {value}\")\n            \n            return applied_optimizations\n    \n    @contextmanager\n    def profiling_session(self, session_name: str = \"inference\"):\n        \"\"\"\n        Profiling会话上下文管理器\n        \n        Args:\n            session_name: 会话名称\n        \"\"\"\n        self.logger.info(f\"Starting profiling session: {session_name}\")\n        \n        # 开始系统监控\n        if self.performance_monitor:\n            self.performance_monitor.start_monitoring(interval=0.5)\n        \n        with self.main_timer.timer(f\"session_{session_name}\"):\n            try:\n                yield self\n            finally:\n                # 停止系统监控\n                if self.performance_monitor:\n                    monitoring_data = self.performance_monitor.stop_monitoring()\n                    self.profiling_results['monitoring_data'] = monitoring_data\n                \n                self.logger.info(f\"Completed profiling session: {session_name}\")\n    \n    def profile_pytorch_model(self, model, inputs: List, num_runs: int = 3, warmup_runs: int = 2, \n                            enable_detailed_analysis: bool = True) -> Dict[str, Any]:\n        \"\"\"\n        深度PyTorch模型profiling\n        \n        Args:\n            model: PyTorch模型\n            inputs: 输入张量列表\n            num_runs: 运行次数\n            warmup_runs: 预热次数\n            enable_detailed_analysis: 是否启用详细的module级分析\n            \n        Returns:\n            PyTorch profiling结果\n        \"\"\"\n        with self.main_timer.timer(\"pytorch_profiling\"):\n            if self.pytorch_profiler is None:\n                self.pytorch_profiler = ModuleProfiler(f\"{self.name}_pytorch\")\n            \n            self.logger.info(f\"Starting PyTorch model profiling ({num_runs} runs, {warmup_runs} warmup)\")\n            \n            results = self.pytorch_profiler.profile_model_inference(\n                model=model,\n                inputs=inputs,\n                num_runs=num_runs,\n                warmup_runs=warmup_runs\n            )\n            \n            # 添加bottleneck分析\n            results[\"bottleneck_analysis\"] = self.pytorch_profiler.get_bottleneck_analysis(results)\n            \n            self.profiling_results['pytorch_results'] = results\n            \n            self.logger.info(f\"PyTorch profiling completed. Found {len(results.get('module_stats', {}))} modules\")\n            \n            return results\n    \n    def profile_onnx_model(self, model_path: str, dataloader, num_batches: Optional[int] = None, \n                         num_threads: Optional[int] = None) -> Dict[str, Any]:\n        \"\"\"\n        深度ONNX模型profiling\n        \n        Args:\n            model_path: ONNX模型路径\n            dataloader: 数据加载器\n            num_batches: 要profile的batch数量\n            num_threads: 线程数\n            \n        Returns:\n            ONNX profiling结果\n        \"\"\"\n        with self.main_timer.timer(\"onnx_profiling\"):\n            if self.onnx_profiler is None:\n                self.onnx_profiler = ONNXProfilerV2(self.output_dir, f\"{self.name}_onnx\")\n            \n            self.logger.info(f\"Starting ONNX model profiling (path: {model_path})\")\n            \n            # 加载并分析模型\n            model_info = self.onnx_profiler.load_and_analyze_model(model_path, num_threads)\n            \n            # 执行详细的推理profiling\n            profiling_results = self.onnx_profiler.profile_inference_detailed(\n                dataloader=dataloader,\n                num_batches=num_batches\n            )\n            \n            results = {\n                'model_info': model_info,\n                'profiling_results': profiling_results\n            }\n            \n            self.profiling_results['onnx_results'] = results\n            \n            total_ops = profiling_results.get('operator_analysis', {}).get('total_operators', 0)\n            self.logger.info(f\"ONNX profiling completed. Analyzed {total_ops} operators\")\n            \n            return results\n    \n    def profile_transformer_layers(self, transformer_model, input_data, \n                                 layer_name_pattern: str = \"layers\") -> Dict[str, Any]:\n        \"\"\"\n        Transformer层级profiling\n        \n        Args:\n            transformer_model: Transformer模型\n            input_data: 输入数据\n            layer_name_pattern: 层名称模式\n            \n        Returns:\n            层级分析结果\n        \"\"\"\n        with self.main_timer.timer(\"transformer_layer_profiling\"):\n            if self.layer_profiler is None:\n                self.layer_profiler = LayerWiseProfiler()\n            \n            self.logger.info(\"Starting Transformer layer profiling\")\n            \n            results = self.layer_profiler.profile_transformer_layers(\n                transformer_model=transformer_model,\n                input_data=input_data,\n                layer_name_pattern=layer_name_pattern\n            )\n            \n            self.logger.info(f\"Transformer layer profiling completed\")\n            \n            return results\n    \n    def generate_comprehensive_report(self, report_name: Optional[str] = None) -> str:\n        \"\"\"\n        生成综合性能报告\n        \n        Args:\n            report_name: 报告名称\n            \n        Returns:\n            生成的报告文件路径\n        \"\"\"\n        with self.main_timer.timer(\"report_generation\"):\n            if report_name is None:\n                timestamp = datetime.now().strftime(\"%Y%m%d_%H%M%S\")\n                report_name = f\"{self.name}_comprehensive_report_{timestamp}\"\n            \n            self.logger.info(f\"Generating comprehensive report: {report_name}\")\n            \n            # 生成文本报告\n            text_report_path = self.visualizer.generate_comprehensive_report(\n                pytorch_results=self.profiling_results.get('pytorch_results'),\n                onnx_results=self.profiling_results.get('onnx_results'),\n                system_info=self.profiling_results.get('system_info'),\n                report_name=report_name\n            )\n            \n            # 生成JSON摘要\n            json_report_path = self.visualizer.generate_json_summary(\n                pytorch_results=self.profiling_results.get('pytorch_results'),\n                onnx_results=self.profiling_results.get('onnx_results'),\n                report_name=f\"{report_name}_summary\"\n            )\n            \n            # 导出timer数据\n            timer_export_path = os.path.join(self.output_dir, f\"{report_name}_timers.json\")\n            self.main_timer.export_to_json(timer_export_path)\n            \n            # 生成优化脚本\n            if self.profiling_results.get('system_info'):\n                script_path = os.path.join(self.output_dir, f\"{report_name}_optimization.sh\")\n                self.cpu_detector.generate_optimization_script(script_path)\n            \n            self.logger.info(f\"Report generation completed:\")\n            self.logger.info(f\"  Text report: {text_report_path}\")\n            self.logger.info(f\"  JSON summary: {json_report_path}\")\n            self.logger.info(f\"  Timer data: {timer_export_path}\")\n            \n            return text_report_path\n    \n    def get_performance_summary(self) -> Dict[str, Any]:\n        \"\"\"\n        获取性能摘要\n        \n        Returns:\n            性能摘要字典\n        \"\"\"\n        summary = {\n            'session_info': {\n                'profiler_name': self.name,\n                'output_directory': self.output_dir,\n                'timestamp': datetime.now().isoformat()\n            },\n            'system_info': self.profiling_results.get('system_info', {}),\n            'optimization_applied': self.profiling_results.get('optimization_applied', {}),\n            'profiling_completed': {}\n        }\n        \n        # 检查完成的profiling任务\n        if self.profiling_results.get('pytorch_results'):\n            pytorch_stats = self.profiling_results['pytorch_results'].get('overall_stats', {})\n            summary['profiling_completed']['pytorch'] = {\n                'total_modules': len(self.profiling_results['pytorch_results'].get('module_stats', {})),\n                'total_runs': self.profiling_results['pytorch_results'].get('total_runs', 0)\n            }\n        \n        if self.profiling_results.get('onnx_results'):\n            onnx_profiling = self.profiling_results['onnx_results'].get('profiling_results', {})\n            summary['profiling_completed']['onnx'] = {\n                'total_operators': onnx_profiling.get('operator_analysis', {}).get('total_operators', 0),\n                'total_batches': onnx_profiling.get('total_batches', 0)\n            }\n        \n        # 添加timer摘要\n        timer_stats = self.main_timer.get_aggregated_stats()\n        timer_percentages = self.main_timer.calculate_percentages()\n        \n        summary['timing_breakdown'] = {\n            name: {\n                'total_time_ms': stat.total_duration_ms,\n                'percentage': timer_percentages.get(name, 0.0),\n                'count': stat.count\n            } for name, stat in timer_stats.items()\n        }\n        \n        return summary\n    \n    def get_optimization_recommendations(self) -> List[Dict[str, str]]:\n        \"\"\"\n        获取综合优化建议\n        \n        Returns:\n            优化建议列表\n        \"\"\"\n        recommendations = []\n        \n        # CPU平台优化建议\n        cpu_recommendations = self.cpu_detector.get_performance_recommendations()\n        recommendations.extend(cpu_recommendations)\n        \n        # 基于profiling结果的建议\n        if self.profiling_results.get('pytorch_results'):\n            pytorch_bottlenecks = self.profiling_results['pytorch_results'].get('bottleneck_analysis', {})\n            pytorch_recs = pytorch_bottlenecks.get('recommendations', [])\n            for rec in pytorch_recs:\n                recommendations.append({\n                    'category': 'PyTorch Performance',\n                    'recommendation': rec,\n                    'priority': 'medium'\n                })\n        \n        if self.profiling_results.get('onnx_results'):\n            onnx_profiling = self.profiling_results['onnx_results'].get('profiling_results', {})\n            onnx_bottlenecks = onnx_profiling.get('bottleneck_analysis', {})\n            onnx_recs = onnx_bottlenecks.get('recommendations', [])\n            for rec in onnx_recs:\n                recommendations.append({\n                    'category': 'ONNX Performance',\n                    'recommendation': rec,\n                    'priority': 'medium'\n                })\n        \n        return recommendations\n    \n    def export_all_data(self, base_filename: Optional[str] = None) -> Dict[str, str]:\n        \"\"\"\n        导出所有profiling数据\n        \n        Args:\n            base_filename: 基础文件名\n            \n        Returns:\n            导出文件路径字典\n        \"\"\"\n        if base_filename is None:\n            timestamp = datetime.now().strftime(\"%Y%m%d_%H%M%S\")\n            base_filename = f\"{self.name}_export_{timestamp}\"\n        \n        export_paths = {}\n        \n        # 导出主要结果数据\n        main_export_path = os.path.join(self.output_dir, f\"{base_filename}_complete.json\")\n        with open(main_export_path, 'w') as f:\n            json.dump(self.profiling_results, f, indent=2, default=str)\n        export_paths['complete_results'] = main_export_path\n        \n        # 导出timer数据\n        timer_path = os.path.join(self.output_dir, f\"{base_filename}_timers.json\")\n        self.main_timer.export_to_json(timer_path)\n        export_paths['timer_data'] = timer_path\n        \n        # 导出性能摘要\n        summary_path = os.path.join(self.output_dir, f\"{base_filename}_summary.json\")\n        summary = self.get_performance_summary()\n        with open(summary_path, 'w') as f:\n            json.dump(summary, f, indent=2, default=str)\n        export_paths['summary'] = summary_path\n        \n        # 导出优化建议\n        recommendations_path = os.path.join(self.output_dir, f\"{base_filename}_recommendations.json\")\n        recommendations = self.get_optimization_recommendations()\n        with open(recommendations_path, 'w') as f:\n            json.dump(recommendations, f, indent=2, default=str)\n        export_paths['recommendations'] = recommendations_path\n        \n        return export_paths\n    \n    def print_summary(self, detailed: bool = False):\n        \"\"\"\n        打印性能摘要\n        \n        Args:\n            detailed: 是否显示详细信息\n        \"\"\"\n        summary = self.get_performance_summary()\n        \n        print(f\"\\n=== TESSERA PROFILER SUMMARY: {self.name} ===\")\n        \n        # 系统信息\n        system_info = summary.get('system_info', {})\n        cpu_info = system_info.get('cpu_info', {})\n        print(f\"CPU: {cpu_info.get('vendor', 'Unknown')} {cpu_info.get('brand', 'Unknown')}\")\n        print(f\"Cores: {cpu_info.get('physical_cores', 'N/A')} physical, {cpu_info.get('logical_cores', 'N/A')} logical\")\n        \n        memory_info = system_info.get('memory_info', {})\n        print(f\"Memory: {memory_info.get('total_gb', 'N/A')} GB total, {memory_info.get('available_gb', 'N/A')} GB available\")\n        \n        # 优化状态\n        optimizations = summary.get('optimization_applied', {})\n        if optimizations:\n            print(f\"CPU Optimizations: {len(optimizations)} applied\")\n        \n        # Profiling结果\n        profiling_completed = summary.get('profiling_completed', {})\n        if 'pytorch' in profiling_completed:\n            pytorch_info = profiling_completed['pytorch']\n            print(f\"PyTorch: {pytorch_info['total_modules']} modules, {pytorch_info['total_runs']} runs\")\n        \n        if 'onnx' in profiling_completed:\n            onnx_info = profiling_completed['onnx']\n            print(f\"ONNX: {onnx_info['total_operators']} operators, {onnx_info['total_batches']} batches\")\n        \n        # 时间分解\n        timing_breakdown = summary.get('timing_breakdown', {})\n        if timing_breakdown and detailed:\n            print(\"\\n⏱️  Timing Breakdown:\")\n            sorted_timings = sorted(timing_breakdown.items(), \n                                  key=lambda x: x[1]['total_time_ms'], \n                                  reverse=True)\n            \n            for name, timing in sorted_timings[:10]:\n                print(f\"  {name:30} {timing['total_time_ms']:8.2f}ms ({timing['percentage']:5.1f}%)\")\n        \n        print(f\"\\nOutput Directory: {self.output_dir}\")\n        print(\"=\"*60)\n    \n    def cleanup(self):\n        \"\"\"\n        清理资源\n        \"\"\"\n        if self.pytorch_profiler:\n            self.pytorch_profiler.cleanup()\n        \n        if self.onnx_profiler:\n            self.onnx_profiler.cleanup()\n        \n        if self.layer_profiler:\n            self.layer_profiler._cleanup_hooks()\n        \n        self.main_timer.clear()\n        \n        self.logger.info(\"TesseraProfiler cleanup completed\")\n\n# 便捷函数\ndef create_tessera_profiler(output_dir: str, name: str = \"tessera_profiler\", \n                          auto_optimize: bool = True, model_type: str = 'onnx') -> TesseraProfiler:\n    \"\"\"\n    创建并初始化TesseraProfiler\n    \n    Args:\n        output_dir: 输出目录\n        name: profiler名称\n        auto_optimize: 是否自动应用CPU优化\n        model_type: 模型类型\n        \n    Returns:\n        TesseraProfiler实例\n    \"\"\"\n    profiler = TesseraProfiler(output_dir, name)\n    \n    if auto_optimize:\n        profiler.optimize_for_cpu(model_type)\n    \n    return profiler